using BmsDesktop.Domain;
namespace BmsDesktop.Security;
public static class AuthorizationService { public static bool Can(AppUser u,string action)=>action switch { "ADMIN_USERS" or "MASTER_DATA" => u.Role==UserRole.ADMIN, "PRODUCTION" => u.Role is UserRole.ADMIN or UserRole.PRODUKSI or UserRole.PPL, "LOGISTICS" => u.Role is UserRole.ADMIN or UserRole.LOGISTIK, "MARKETING" => u.Role is UserRole.ADMIN or UserRole.MARKETING, "FINANCE" => u.Role is UserRole.ADMIN or UserRole.KEUANGAN, "CASH_REQUEST" => u.Role is UserRole.ADMIN or UserRole.KEUANGAN, "GLOBAL_REPORT" => u.Role is UserRole.ADMIN or UserRole.KEUANGAN or UserRole.OWNER, "RESTORE" => u.Role is UserRole.ADMIN or UserRole.OWNER, _=>false}; public static void Demand(AppUser u,string action){if(!Can(u,action))throw new UnauthorizedAccessException("Akses ditolak untuk role "+u.Role+".");} }
